Bash cat >> app/page.tsx <<'EOF'

function PollCard({
  poll,
  members,
  me,
  showNotMe,
}: {
  poll: Poll;
  members: Member[];
  me: Member | null;
  showNotMe: boolean;
}) {
  if (poll.closed) {
    const winner = poll.candidates.find((c) => c.id === poll.winnerId);
    const others = poll.candidates.filter((c) => c.id !== poll.winnerId).sort((a, b) => b.votes - a.votes);
    return (
      <Card>
        <p className="text-xs font-semibold uppercase tracking-wider text-stone-500">The vote is in</p>
        {winner && (
          <p className="mt-1 font-serif text-xl font-semibold">
            {winner.title}
            {winner.author && <span className="font-sans text-base font-normal text-stone-600"> by {winner.author}</span>}
            <span className="ml-2 font-sans text-sm font-normal text-stone-500">({votesLabel(winner.votes)})</span>
          </p>
        )}
        {others.length > 0 && (
          <ul className="mt-3 space-y-1 text-sm text-stone-600">
            {others.map((c) => (
              <li key={c.id}>
                {c.title} · {votesLabel(c.votes)}
              </li>
            ))}
          </ul>
        )}
      </Card>
    );
  }

  const myVote = me ? poll.votes.find((v) => v.member_id === me.id)?.candidate_id : undefined;
  const voterCount = new Set(poll.votes.map((v) => v.member_id)).size;

  return (
    <Card>
      <div className="flex items-baseline justify-between gap-4">
        <h2 className="font-serif text-lg font-semibold">Vote for the next book</h2>
        {me && showNotMe && <NotMe me={me} />}
      </div>
      <p className="mt-1 text-sm text-stone-500">
        {voterCount} of {members.length} voted · {me ? "You can change your vote until it closes." : "Pick your name above to vote."}
      </p>

      <form action={castVote} className="mt-4 space-y-2">
        <input type="hidden" name="pollId" value={poll.id} />
        {poll.candidates.map((c) => {
          const mine = myVote === c.id;
          return (
            <button
              key={c.id}
              type="submit"
              name="candidateId"
              value={c.id}
              disabled={!me}
              aria-pressed={mine}
              className={`block w-full rounded-lg border px-4 py-3 text-left transition ${
                mine
                  ? "border-stone-800 bg-stone-800 text-white"
                  : "border-stone-300 bg-white hover:bg-stone-50 disabled:cursor-default disabled:hover:bg-white"
              }`}
            >
              <span className="font-medium">
                {mine && "✓ "}
                {c.title}
              </span>
              {c.author && <span className={mine ? "text-stone-300" : "text-stone-500"}> by {c.author}</span>}
            </button>
          );
        })}
      </form>
    </Card>
  );
}

function votesLabel(n: number) {
  return `${n} ${n === 1 ? "vote" : "votes"}`;
}
EOF

